import{H as e,gt as t,nt as n,tt as r}from"./chunks/framework.sms2Rnvf.js";import"./chunks/assets.CKUgKlCM.js";var i=JSON.parse(`{"title":"AD Privileged Access Strategy","description":"","frontmatter":{"search":{"exclude":true},"grammarly":false},"headers":[],"relativePath":"d/ad/privileged-access-strategy.md","filePath":"d/ad/privileged-access-strategy.md","lastUpdated":1781102819000}`),a={name:`d/ad/privileged-access-strategy.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /d/ad/privileged-access-strategy.md for this page in Markdown format</div><h1 id="ad-privileged-access-strategy" tabindex="-1">AD Privileged Access Strategy <a class="header-anchor" href="#ad-privileged-access-strategy" aria-label="Permalink to “AD Privileged Access Strategy”">​</a></h1><h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to “Description”">​</a></h2><p>The Privileged Access strategy is part of an overall strategy for access control in an enterprise. The Enterprise Access Model shows how privileged access can be securely managed in an enterprise.</p><p><img src="/images/user-app-control-management-data-workload-planes.png" alt="Enterprise Access Model" width="1461" height="796"> Source: <a href="https://learn.microsoft.com/en-us/security/compass/media/privileged-access-strategy/user-app-control-management-data-workload-planes.png" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/security/compass/media/privileged-access-strategy/user-app-control-management-data-workload-planes.png</a></p><p>The applications and data of an organisation usually store a large part of the company&#39;s value. This information, which requires special protection, is held in the <strong>Data/Workload Plane</strong> in the Enterprise Access Model.</p><p>The <strong>Management Plane</strong> comprises the infrastructure that provides the applications and data of the Data/Workload Plane. Management is the responsibility of the corporate IT organisation, whether hosted on-premise, in Azure or with a third-party cloud provider.</p><p>Providing consistent access control for these systems across the enterprise requires a <strong>Control Plane</strong>. This is based on centralised identity management systems, complemented by network access controls.</p><p>For these systems to add operational value, they must be accessible to internal users, suppliers and customers, e.g. via their workstations or other devices (access via <strong>User Access</strong>). Application programming interfaces (APIs) are also often necessary for process automation, creating access paths through applications (<strong>App Access</strong>).</p><p>Finally, these systems need to be managed by IT staff, developers or other company employees. This leads to privileged access paths (<strong>Privileged Access</strong>). These access paths are particularly critical and should be strictly protected against compromise.</p><h2 id="recommendation" tabindex="-1">Recommendation <a class="header-anchor" href="#recommendation" aria-label="Permalink to “Recommendation”">​</a></h2><p>We recommend implementing a privileged access strategy as part of an overall access control strategy in an organization based on the enterprise access model.</p>`,12)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};